const rows = $input.all().map(i => i.json);
const target = rows.find(r => String(r['상태'] || '').trim() === '사진완료');
if (!target) return [];
return [{ json: target }];

function escHtml(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

var CARD_CSS = ":root{--panel:#6e6684;--canvas:#000000;--ink:#ffffff;--ink-body:#f2f0f5;--ink-muted:#d6d2de;--accent:#f0e2c8;--pad:72px}*{box-sizing:border-box;margin:0;padding:0}html,body{width:1080px;height:1350px}body{background:var(--canvas);display:flex;flex-direction:column;overflow:hidden;position:relative;font-family:'Noto Sans KR',sans-serif}.photo{flex:1 1 auto;min-height:0;position:relative}.photo img{width:100%;height:100%;object-fit:cover;display:none}.photo:after{content:'';position:absolute;left:0;right:0;bottom:0;height:200px;background:linear-gradient(to top,rgba(0,0,0,.55),transparent);z-index:1;pointer-events:none}.credit{position:absolute;right:30px;bottom:18px;z-index:2;max-width:calc(100% - 60px);text-align:right;font-size:26px;font-weight:400;color:rgba(255,255,255,.8);letter-spacing:.01em;text-shadow:0 1px 4px rgba(0,0,0,.6)}.src:before{content:' \00b7 '}.src:empty{display:none}.cap:empty + .src:before{content:''}.panel{flex:0 0 580px;background:var(--panel);padding:46px var(--pad) 38px;display:flex;flex-direction:column;overflow:hidden}.eyebrow{display:none;font-size:30px;font-weight:500;color:var(--accent);letter-spacing:.06em;margin-bottom:14px}.headline{font-size:54px;font-weight:700;color:var(--ink);line-height:1.2;letter-spacing:-.02em;word-break:keep-all;overflow-wrap:anywhere}.body{font-size:34px;font-weight:400;color:var(--ink-body);line-height:1.45;margin-top:22px;word-break:keep-all;overflow-wrap:anywhere}.rule{display:none}.cta{display:none}.meta{display:flex;justify-content:space-between;align-items:baseline;font-size:26px;color:var(--ink-muted);margin-top:auto;padding-top:30px;font-variant-numeric:tabular-nums}[data-role='표지'] .ph{display:block}[data-role='표지'] .panel{flex:0 0 500px;padding-top:58px}[data-role='표지'] .headline{font-size:56px;line-height:1.2}[data-role='표지'] .body{font-size:34px;margin-top:26px}[data-role='본문'] .ph{display:block}[data-role='본문'] .eyebrow{display:block}[data-role='클로징']{background:var(--panel)}[data-role='클로징'] .photo{display:none}[data-role='클로징'] .panel{flex:1 1 auto;min-height:0;background:transparent;padding:0 var(--pad);justify-content:center;align-items:center;text-align:center}[data-role='클로징'] .headline{font-size:52px;line-height:1.35}[data-role='클로징'] .body{font-size:35px;line-height:1.55;margin-top:30px;color:var(--ink-muted)}[data-role='클로징'] .rule{display:block;width:96px;height:2px;background:var(--ink-muted);opacity:.55;margin:52px 0 30px}[data-role='클로징'] .cta{display:block;font-size:32px;font-weight:500;color:var(--ink)}[data-role='클로징'] .meta{position:absolute;left:var(--pad);right:var(--pad);bottom:44px;margin:0}";

function buildCardHtml(slide, photoUrl, creditText, total) {
  var no = slide.no;
  var role = slide.role;
  var caption = escHtml(slide.photo_caption);
  var credit = escHtml(creditText);
  var eyebrow = (no >= 10 ? String(no) : '0' + no) + ' · 리테일';
  var headline = escHtml(slide.headline);
  var body = escHtml(slide.body);
  return '<!doctype html><html lang="ko"><head><meta charset="utf-8">'
    + '<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&display=swap" rel="stylesheet">'
    + '<style>' + CARD_CSS + '</style></head>'
    + '<body data-role="' + role + '">'
    + '<div class="photo"><img class="ph" src="' + (photoUrl || '') + '" alt="">'
    + '<div class="credit"><span class="cap">' + caption + '</span><span class="src">' + credit + '</span></div></div>'
    + '<div class="panel"><div class="eyebrow">' + eyebrow + '</div>'
    + '<div class="headline">' + headline + '</div>'
    + '<div class="body">' + body + '</div>'
    + '<div class="rule"></div><div class="cta">@inseoul_curation</div>'
    + '<div class="meta"><span>서울 · 리테일 · 공간</span><span>' + no + '/' + total + '</span></div>'
    + '</div></body></html>';
}


const row = $input.first().json;
const draft = JSON.parse(row['원고JSON']);
const slides = draft.slides || [];
const photos = String(row['사진URL'] || '').split(',');
const credits = String(row['사진출처'] || '').split(',');
const total = slides.length;

return slides.map(function (slide) {
  const no = slide.no;
  const photoUrl = slide.role === '클로징' ? '' : (photos[no - 1] || '');
  const credit = credits[no - 1] || '';
  const html = buildCardHtml(slide, photoUrl, credit, total);
  return { json: { no: no, body: { html: html, width: 1080, height: 1350, dpi: 1, ms_delay: 3000 } } };
});

const originals = $('슬라이드별 html2img 요청 생성').all();
const responses = $input.all();
const total = originals.length;
const urls = new Array(total).fill('');
responses.forEach(function (resp, i) {
  const no = originals[i].json.no;
  const url = (resp.json && resp.json.data) ? resp.json.data.url : '';
  urls[no - 1] = url || '';
});
const rowInfo = $('사진완료 행 찾기').item.json;
return [{ json: { row_number: rowInfo.row_number, render_urls: urls.join(',') } }];
